      "content": "{\n  \"name\": \"deepseek-flow\",\n  \"version\": \"0.4.2\",\n  \"description\": \"DeepSeek Flow — Markdown-first visual workflow plugin for DeepSeek Harness with executable Boolean gate semantics, two-way canvas sync, and AI review/optimization.\",\n  \"license\": \"MIT\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/kanghelyu/dsh-deepseek-flow.git\"\n  },\n  \"homepage\": \"https://github.com/kanghelyu/dsh-deepseek-flow#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/kanghelyu/dsh-deepseek-flow/issues\"\n  },\n  \"keywords\": [\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"dsh\",\n    \"workflow\",\n    \"boolean-logic\",\n    \"visual-editor\",\n    \"markdown\"\n  ],\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./logic\": \"./lib/logic-semantics.js\",\n    \"./typert\": \"./lib/typert.host.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"src\",\n    \"scripts\",\n    \"test\",\n    \"examples\",\n    \"skills\",\n    \"qa/*v9*.png\",\n    \"docs/images\",\n    \"README.md\",\n    \"README.zh-CN.md\",\n    \"DEEPSEEKFLOW-GUIDE.md\",\n    \"DEEPSEEKFLOW-使用说明.md\",\n    \"CHANGELOG.md\",\n    \"CODE-QUALITY.md\",\n    \"LICENSE\",\n    \"QA-REPORT.md\",\n    \"HANDOFF-0.3.5.md\",\n    \"cordis.patch.yml\",\n    \"pnpm-lock.yaml\",\n    \"pnpm-workspace.yaml\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-slots\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node scripts/build.mjs\",\n    \"deps:check\": \"bash scripts/ensure-deps.sh\",\n